%% put the lat and lon into a table

% Reshape into 3 columns: [lon, lat, alt]
n_points = numel(all_raw_GPS_coordinates) / 3;
table_raw_GPS_coordinates = reshape(all_raw_GPS_coordinates, 3, n_points)';  % each row = [lon, lat, alt]



%%
% Read the file (assuming it's space or comma separated)
data = readmatrix('20250812035240-96075-data.txt');

% Altitude is the 3rd column in KML-like GPS coordinates [lon, lat, alt]
altitude = data(:,4);

alt = altitude;



%% Genearte Cartesian coordinates
lat = table_raw_GPS_coordinates(:, 2);
lon = table_raw_GPS_coordinates(:, 1);
origin =  [table_raw_GPS_coordinates(1, 2), table_raw_GPS_coordinates(1, 1), alt(1)];
[xEast_C_GE_raw, yNorth_C_GE_raw, zUp_C_GE_raw] = latlon2local(lat, lon, alt, origin);



%% Plot the Cartesian coordinates
figure()
plot3(xEast_C_GE_raw, yNorth_C_GE_raw, zUp_C_GE_raw - min(zUp_C_GE_raw), '-o')
hold on
plot3(xEast_C_GE_raw, yNorth_C_GE_raw, zUp_C_GE_raw*0, '-o')
axis equal
xlabel('x, m')
ylabel('y, m')
zlabel('z, m')
% legend('From shanghai\_centerline\_path\_only.kml and https://www.gpsvisualizer.com/elevation', 'Projection to the x-y plane')
grid on



%% Save
save('C_Cartesian_coords_GE_raw', 'xEast_C_GE_raw', 'yNorth_C_GE_raw', 'zUp_C_GE_raw')
save('origin', 'origin')


%% calculate the rotation angle so that the big straight of the track is aligned with x axis

% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% % pick up two points on the straight line of the track, from the figure
% % above
% % only use absolute value here for the angle
% angle_to_rotate_in_rad = atan2(572.36, 361.299); % [rad]
% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% 
% save('origin_GPS', 'origin')
% save('Google_Earth_track_info', 'xEast', 'yNorth', 'zUp', 'angle_to_rotate_in_rad')



%% Generate left and right boundaries of the circuit for Google Earth Pro
% two .kml files will be generated. You can load them into Google Earth Pro
% respectively and manually adjust them again to better overlay with the
% left and right boundaries of the circuit in Google Earth.
% ————————————————————————————————————————
% INPUT: centre‐line in ENU (from your .kml via latlon2local)
%    xE, yN, zU   (Nx1 vectors)
%    origin       = [lat0, lon0, alt0]   (your first point)
% halfWidth      = desired half‐track width (m)
% ————————————————————————————————————————
halfWidth = 7; % this is only a rough estimate of the half width of the track

% 1) compute true arc‐length s along centre‐line
ds = [0; sqrt(diff(xEast_C_GE_raw).^2 + diff(yNorth_C_GE_raw).^2)];  
s  = cumsum(ds);          % (Nx1)

% 2) get the unit tangent t = [tx;ty] = d(xE,yN)/ds
tx = gradient(xEast_C_GE_raw, s);     % d xE / d s
ty = gradient(yNorth_C_GE_raw, s);     % d yN / d s
t_norm = hypot(tx, ty);   % should be ≈1
tx = tx ./ t_norm;        % enforce unit length
ty = ty ./ t_norm;

% 3) rotate 90° CCW to get outward unit normal n = [nx; ny]
nx = -ty;
ny =  tx;

% 4) offset centre‐line to left & right rails
xL = xEast_C_GE_raw +  halfWidth .* nx;
yL = yNorth_C_GE_raw +  halfWidth .* ny;
zL = zUp_C_GE_raw;                   % same up

xR = xEast_C_GE_raw -  halfWidth .* nx;
yR = yNorth_C_GE_raw -  halfWidth .* ny;
zR = zUp_C_GE_raw;

% 5) convert ENU back to geodetic for KML
%    (requires Mapping Toolbox)
ell = wgs84Ellipsoid;  
[latL, lonL, altL] = enu2geodetic(xL, yL, zL, ...
                                 origin(1), origin(2), origin(3), ell);
[latR, lonR, altR] = enu2geodetic(xR, yR, zR, ...
                                 origin(1), origin(2), origin(3), ell);

% % % 6) write out KMLs
% % kmlwriteline('leftBoundary_new_new.kml', latL, lonL, altL*0, ...
% %              'Name','LeftBoundary', ...
% %              'Description','Shifted 8 m left of center');
% % 
% % kmlwriteline('rightBoundary_new_new.kml', latR, lonR, altR*0, ...
% %              'Name','RightBoundary', ...
% %              'Description','Shifted 8 m right of center');
% 


